@TestOn('browser')
library;

import 'dart:convert';
import 'dart:typed_data';

import 'package:test/test.dart';
import 'package:unseal/epub.dart';

/// Browser equivalence for the EPUB diagnostics contract: the same
/// committed fixture bytes produce the same findings through dart2js as
/// the VM suite asserts in test/tests/epub/epub_diagnostics_test.dart.
/// Expectations mirror test/resources/epub/diagnostics/manifest.json.
///
/// Run with: dart test test/web --platform chrome
void main() {
  group('EPUB diagnostics on the browser', () {
    test('clean EPUB 3 baseline reports no findings', () {
      final report = diagnoseEpub(_decode(_epub3Valid));
      expect(report.findings, isEmpty);
      expect(report.rootFilePath, 'OEBPS/content.opf');
      expect(report.truncated, isFalse);
    });

    test('missing manifest resource is reported with rule and location', () {
      final report = diagnoseEpub(_decode(_manifestResourceMissing));
      expect(report.findings.map((final finding) => finding.ruleId), [
        'epub.manifest.resource-missing',
      ]);
      expect(report.findings.single.resource, 'OEBPS/ghost.png');
      expect(report.findings.single.location, 'manifest item "ghost"');
    });

    test('unresolved NCX link is reported like on the VM', () {
      final report = diagnoseEpub(_decode(_ncxLinkUnresolved));
      expect(report.findings.map((final finding) => finding.ruleId), [
        'epub.navigation.link-unresolved',
      ]);
      expect(report.findings.single.resource, 'OEBPS/absent.xhtml');
    });
  });
}

Uint8List _decode(final String base64) => base64Decode(base64);

const _epub3Valid =
    '''''';

const _manifestResourceMissing =
    '''''';

const _ncxLinkUnresolved =
    '''''';
